-- Galactic Station v4 Data Card diagnostic.
-- Uses the documented component.methods + component.invoke APIs.
-- Does not display generated bytes, keys, or secrets.
-- Run: lua /tmp/data_card_check.lua

local component = require("component")

local function say(value) print(tostring(value)) end
local function available(methods, name)
  -- component.methods values indicate direct-call support; a method exists
  -- whenever the key is present, even when its value is false.
  return methods[name] ~= nil
end

say("============================================================")
say(" GALACTIC STATION | DATA CARD DIAGNOSTIC")
say("============================================================")

local count = 0
for address, typeName in component.list("data", true) do
  count = count + 1
  say("")
  say("Data component #" .. tostring(count))
  say("Address: " .. tostring(address))
  say("Component type: " .. tostring(typeName))

  local methodsOK, methods = pcall(component.methods, address)
  if not methodsOK or type(methods) ~= "table" then
    say("component.methods failed: " .. tostring(methods))
  else
    local names = {}
    for name in pairs(methods) do names[#names + 1] = tostring(name) end
    table.sort(names)
    say("Methods: " .. table.concat(names, ", "))

    local required = {"sha256", "encrypt", "decrypt", "random"}
    say("Required Tier 2+ methods:")
    for _, name in ipairs(required) do
      say("  " .. name .. ": " .. (available(methods, name) and "AVAILABLE" or "MISSING"))
    end

    local tier3 = {"generateKeyPair", "deserializeKey", "ecdh", "ecdsa"}
    say("Tier 3 asymmetric methods:")
    for _, name in ipairs(tier3) do
      say("  " .. name .. ": " .. (available(methods, name) and "AVAILABLE" or "MISSING"))
    end

    if available(methods, "sha256") then
      local ok, digest = pcall(component.invoke, address, "sha256", "abc")
      say("SHA-256 invocation: " ..
        (ok and type(digest) == "string" and #digest == 32 and "PASS (32-byte digest)" or "FAIL: " .. tostring(digest)))
    end

    if available(methods, "random") then
      local ok, bytes = pcall(component.invoke, address, "random", 16)
      say("Random invocation: " ..
        (ok and type(bytes) == "string" and #bytes == 16 and "PASS (16 bytes)" or "FAIL: " .. tostring(bytes)))
    end

    if available(methods, "encrypt") and available(methods, "decrypt") then
      local plain = "GALACTIC-STATION-DATA-CARD-TEST"
      local testKey = "0123456789ABCDEF"
      local testIV = "FEDCBA9876543210"
      local encOK, cipher = pcall(component.invoke, address, "encrypt", plain, testKey, testIV)
      if encOK and type(cipher) == "string" then
        local decOK, decoded = pcall(component.invoke, address, "decrypt", cipher, testKey, testIV)
        say("AES round-trip: " .. (decOK and decoded == plain and "PASS" or "FAIL: " .. tostring(decoded)))
      else
        say("AES round-trip: FAIL: " .. tostring(cipher))
      end
    end
  end
end

if count == 0 then
  say("")
  say("No component of type 'data' detected.")
else
  say("")
  say("Detected data components: " .. tostring(count))
  say("All method checks use component.methods() and calls use component.invoke().")
end

say("============================================================")
